int findNearest(double target, List<double> list) {
  int closestIndex = -1;
  double minDiff = double.infinity;

  for (int index = 0; index < list.length; index++) {
    double diff = abs(list[index] - target);

    if (diff < minDiff) {
      minDiff = diff;
      closestIndex = index;
    } else if (diff == minDiff) {
      // If there's a tie, choose the first occurrence
      if (closestIndex == -1 || index < closestIndex) {
        closestIndex = index;
      }
    }
  }

  return closestIndex;
}

