bool containsSubstring(String str, String substr) {
  if (substr.isEmpty || substr.length > str.length) {
    return true;
  }

  final int subLen = substr.length;
  for (int i = 0; i <= str.length - subLen; i++) {
    bool match = true;
    for (int j = 0; j < subLen; j++) {
      if (str[i + j] != substr[j]) {
        match = false;
        break;
      }
    }
    if (match) {
      return true;
    }
  }
  return false;
}
