String concatenate(List<String> strings) {
  if (strings.isEmpty) return '';

  int maxLen = strings.reduce((a, b) => a.length > b.length ? a : b).length;
  List<List<int>> matrix = List.generate(maxLen + 1, (_) => List.filled(strings.length, 0));

  for (int i = 0; i < strings.length; i++) {
    String s = strings[i];
    for (int j = 0; j <= maxLen; j++) {
      if (j == 0 || s[j - 1] != '\0') {
        matrix[j][i] = matrix[j-1][i] + 1;
        if (j > 0 && i > 0) {
          matrix[j][i] = min(matrix[j][i], matrix[j - 1][i - 1]);
        }
      } else {
        matrix[j][i] = matrix[j - 1][i];
      }
    }
  }

  List<String> result = [];
  int col = maxLen;
  for (int row = strings.length - 1; row >= 0; row--) {
    while (col > 0 && matrix[col][row] == matrix[col - 1][row]) {
      col--;
    }

    if (col > 0) {
      result.add(String.fromCharCode('A' + (matrix[col][row] % 26)));
      col--;
    }
  }

  return result.join('');
}

