  int n = l.length;
  for (int i = 0; i < n - 1; i++) {
    final j = i + random.nextInt(n - i);
    final temp = l[i];
    l[i] = l[j];
    l[j] = temp;
  }

  List<int> result = [];
  Set<int> seen = {};

  for (final item in l) {
    if (!seen.contains(item)) {
      seen.add(item);
      result.add(item);
    }
  }

  return result;
}

