List<int> strangeSortList(List<int> lst) {
  List<int> res = [];
  List<int> remaining = List.from(lst);
  bool useMin = true;

  while (remaining.isNotEmpty) {
    int value;
    if (useMin) {
      value = remaining.reduce((a, b) => a < b ? a : b);
    } else {
      value = remaining.reduce((a, b) => a > b ? a : b);
    }
    res.add(value);
    remaining.remove(value);
    useMin = !useMin;
  }

  return res;
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(strangeSortList([1, 2, 3, 4])); // [1, 4, 2, 3]
  print(strangeSortList([5, 5, 5, 5])); // [5, 5, 5, 5]
  print(strangeSortList([])); // []
  print(strangeSortList([1])); // [1]
  print(strangeSortList([1, 2])); // [1, 2]
  print(strangeSortList([5, 6, 7, 8, 9])); // [5, 9, 6, 8, 7]
  print(strangeSortList([1, 2, 3, 4, 5])); // [1, 5, 2, 4, 3]
}

