import 'dart:math';

String solve(int n) {
  // Edge case for n=0 and n=1
  if (n == 0 || n == 1) return '0';

  // Convert to binary string without leading zeros
  String binStr = n.toRadixString(2);

  // Split into groups of three bits, starting from the end
  List<String> chunks = [];
  for (int i = binStr.length - 1; i >= 0; i -= 3) {
    int start = max(0, i - 2);
    String chunk = binStr.substring(start, i+1);
    chunks.add(chunk);
  }

  // Reverse the chunks to get correct order
  chunks = chunks.reversed.toList();

  // Join with commas between chunks
  return chunks.join(',');
}
