import 'dart:math';

String antiShuffle(String s) {
  if (s.isEmpty || s.length == 1) return s;

  List<String> words = s.split(' ');
  int n = words.length;

  // Create a list to store the shuffled characters for each word
  List<List<String>> shuffledChars = List.generate(n, (_) => []);

  // First pass: collect all characters from each word into separate lists
  for (int i = 0; i < n; ++i) {
    String word = words[i];
    int len = word.length;
    for (int j = 0; j < len; ++j) {
      shuffledChars[i].add(word[j]);
    }
  }

  // Second pass: shuffle and reassemble the words
  for (int i = 0; i < n; ++i) {
    List<String> chars = shuffledChars[i];
    Random rng = Random();

    // Shuffle the characters in-place using Fisher-Yates algorithm
    for (int k = chars.length - 1; k > 0; --k) {
      int r = rng.nextInt(k + 1);
      String temp = chars[k];
      chars[k] = chars[r];
      chars[r] = temp;
    }

    // Reconstruct the word by joining the shuffled characters
    words[i] = chars.join('');
  }

  // Join all the words back together with spaces
  return words.join(' ');
}
