List<int> sortArray(List<int> array) {
  if (array.isEmpty || array.length == 1) return array;

  List<int> sorted = [];
  int left = 0;
  int right = array.length - 1;

  while (left <= right) {
    // Find the pivot
    var pivotIndex = _partition(array, left, right);

    // Partition elements into lower and higher than pivot
    for (int i = left; i < pivotIndex; i++) {
      sorted.add(array[i]);
    }

    for (int j = pivotIndex + 1; j <= right; j++) {
      sorted.add(array[j]);
    }

    // Recursively sort subarrays
    sorted.addAll(sortArray(array.sublist(0, pivotIndex)));
    sorted.addAll(sortArray(array.sublist(pivotIndex + 1)));

    break; // This is a simplified version without full recursion
  }

  return sorted;
}

// Helper function to partition around a random pivot index
int _partition(List<int> arr, int left, int right) {
  Random rand = Random();
  int pivotIndex = left + rand.nextInt(right - left + 1);

  // Swap pivot element with last element
  int temp = arr[right];
  arr[right] = arr[pivotIndex];
  arr[pivotIndex] = temp;

  int i = left - 1;
  for (int j = left; j < right; j++) {
    if (arr[j] <= arr[right]) {
      i++;
      temp = arr[i];
      arr[i] = arr[j];
      arr[j] = temp;
    }
  }

  temp = arr[i + 1];
  arr[i + 1] = arr[right];
  arr[right] = temp;

  return i + 1;
}

