int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // We need to find the maximum number of cells that can be filled
  // with a total sum not exceeding [capacity].

  // First, calculate the prefix sums for each row.
  List<List<int>> rowPrefixSums = [];
  for (final row in grid) {
    List<int> currentRowSum = [0];
    for (int val in row) {
      currentRowSum.add(currentRowSum.last + val);
    }
    rowPrefixSums.add(currentRowSum);
  }

  // Now perform a dynamic programming approach:
  // dp[i][j] represents the maximum number of cells we can fill considering first i rows and j columns.

  final n = rows; 
  final m = cols;

  final dp = List.generate(n + 1, (_) => List.filled(m + 1, 0));

  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      final cellValue = grid[i - 1][j - 1];

      // Option 1: Don't take this cell. Then dp[i][j] is same as previous state
      dp[i][j] = dp[i][j - 1]; 

      // Option 2: Take this cell. Need to check if it's possible.
      // If taking this cell doesn't exceed the capacity,
      // then add the value from the last column up to current column.
      final sumFromLastColToCurrent = rowPrefixSums[i - 1][j] - rowPrefixSums[i - 1][j - 1];
      if (sumFromLastColToCurrent <= capacity) {
        dp[i][j] = max(dp[i][j], dp[i - 1][j - 1] + 1);  
      } else {
        // Can't include any new cell here since even one would exceed capacity
        continue;
      }
    }
  }

  return dp[n][m];
}

