    final row = cell[0];
    final col = cell[1];

    final currentCellCapacity = grid[row][col];
    final availableSpace = min(currentCellCapacity, capacity);

    result += availableSpace;

    for (final dir in directions) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];

