    [0, 1],   // right
    [-1, 0],  // up
    [0, -1]   // left
  ];

  var visited = List.generate(rows, (_) => List.filled(cols, false));

  void dfs(int r, int c, int currentCapacity) {
    if (r < 0 || r >= rows || c < 0 || c >= cols || visited[r][c]) {
      return;
    }

    if (grid[r][c] > currentCapacity) {
      return; // Can't carry this item
    }

    // Mark as visited
    visited[r][c] = true;

    // Try all four directions
    for (final dir in dirs) {
      final nr = r + dir[0];
      final nc = c + dir[1];

      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
        dfs(nr, nc, currentCapacity);
      }
    }
  }

  var result = 0;

  for (var i = 0; i < rows; ++i) {
    for (var j = 0; j < cols; ++j) {
      if (!visited[i][j]) {
        dfs(i, j, capacity); 
        result++;
      }
    }
  }

  return result;
}

