void _siftDownMax(List<int> heap, int start, int end) {
  var root = start;
  while (true) {
    final leftChild = 2 * root + 1;
    final rightChild = 2 * root + 2;

    var swapIndex = root;

    if (leftChild <= end && heap[leftChild] > heap[root]) {
      swapIndex = leftChild;
    }

    if (rightChild <= end && heap[rightChild] > heap[swapIndex]) {
      swapIndex = rightChild;
    }

    if (swapIndex != root) {
      final temp = heap[root];
      heap[root] = heap[swapIndex];
      heap[swapIndex] = temp;
      root = swapIndex;
    } else {
      break;
    }
  }
}

