void backtrack(List<List<int>> grid, List<List<int>> dp, int i, int j, int remainingSteps, List<int> currentPath, List<int> result) {
  if (remainingSteps == 0) {
    if (currentPath.isEmpty) {
      result.add(0); // initial value for empty path
    } else {
      result.add(currentPath.last);
    }
    return;
  }

  if (i >= 0 && j >= 0 && i < grid.length && j < grid[0].length) { 
    if (i == 0 && j == 0) {
      // Start at origin, move either right or down
      backtrackingStep(grid, dp, i+1, j, remainingSteps - 1, [...currentPath, grid[i][j]], result);
      backtrackingStep(grid, dp, i, j+1, remainingSteps - 1, [...currentPath, grid[i][j]], result);
    } else {
      // Move up and left as possible
      backtrackingStep(grid, dp, i-1, j, remainingSteps - 1, [...currentPath, grid[i][j]], result);
      backtrackingStep(grid, dp, i, j-1, remainingSteps - 1, [...currentPath, grid[i][j]], result);
    }
  }
}

