List<int> minPath(List<List<int>> grid, int k) {
  if (grid == null || grid.isEmpty || grid[0].isEmpty) return [];

  final rows = grid.length;
  final cols = grid[0].length;

  // Initialize a priority queue to store the path cost and position
  var pq = PriorityQueue<QueueElement>();
  pq.add(QueueElement(0, 0, 0)); // (cost, row, col)

  // Keep track of visited positions with their minimum costs
  var dist = List.generate(rows * cols, (_) => int.maxValue);
  dist[0] = 0; // Starting at top-left

  while (!pq.isEmpty) {
    var current = pq.removeMin();

    // If we reached the bottom-right corner, check if it's the first time we've reached it or if there's a smaller cost
    if (current.row == rows - 1 && current.col == cols - 1) {
      return [current.cost];
    }

    for (var neighbor in getNeighbors(current.row, current.col, rows, cols)) {
      final newCost = current.cost + grid[neighbor.row][neighbor.col];

      // Update distance if this is better than previous known distance
      if (newCost < dist[neighbor.row * cols + neighbor.col]) {
        dist[neighbor.row * cols + neighbor.col] = newCost;
        pq.add(QueueElement(newCost, neighbor.row, neighbor.col));
      }
    }
  }

  throw Exception('No valid path found');
}

class QueueElement implements Comparable<QueueElement> {
  final int cost;
  final int row;
  final int col;

  QueueElement(this.cost, this.row, this.col);

  @override
  int compareTo(other) {
    return cost.compareTo(other.cost);
  }
}

// Helper function to get neighbors (up/down/left/right)
List<QueueElement> getNeighbors(int r, int c, int rows, int cols) {
  final directions = [
    [-1, 0], [1, 0], [0, -1], [0, 1]
  ];
  final result = <QueueElement>[];

  for (final dir in directions) {
    final newRow = r + dir[0];
    final newCol = c + dir[1];

    if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
      result.add(QueueElement(0, newRow, newCol));
    }
  }

  return result;
}

