List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  if (rows == 0) return [];
  final cols = grid[0].length;

  // Initialize a list to keep track of the minimum path sums for each cell
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  // Base case: first row and first column are initialized with cumulative sum from start
  dp[0][0] = grid[0][0];
  for (int i = 1; i < rows; i++) {
    dp[i][0] = dp[i - 1][0] + grid[i][0];
  }
  for (int j = 1; j < cols; j++) {
    dp[0][j] = dp[0][j - 1] + grid[0][j];
  }

  // Fill up the rest of the DP table
  for (int i = 1; i < rows; i++) {
    for (int j = 1; j < cols; j++) {
      dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j];
    }
  }

  // Find the smallest value in the last row that is at least k
  var result = [dp[rows-1][cols-1]];
  for (int i = rows-2; i >= 0; i--) {
    result.add(dp[i][cols-1]);
  }

  var idx = result.indexWhere((value) => value >= k);
  if (idx != -1) {
    // Reconstruct the path once we've found the correct index
    List<int> path = [grid[idx][cols-1]];
    int x = idx;
    for (int y = cols-2; y >= 0; y--) {
      int nextX = (x > 0 && dp[x - 1][y] <= dp[x][y]) ? x - 1 : x;
      path.insert(0, grid[nextX][y]);
      x = nextX;
    }

    // If there's more than one option (i.e., multiple paths have same minimal sum), choose the lex smaller one
    while (path.length > 0 && path.last == k) {
      path.removeLast();
    }

    return path;
  } else {
    return [];
  }
}

